/// A builder method whose value became a positional argument in front of the main handler,
/// with what is written when the chain never called it: `TextField().text(t)` is
/// `TextField!(t, on_value_change)`.
pub const DATA_METHODS: &[(&str, &str, &str)] = &[("TextField", "text", "\"\"")];

/// Methods whose parameter has another name: `(widget or "*", method, parameter)`.
pub const RENAMES: &[(&str, &str, &str)] = &[
    ("ProgressIndicator", "indicator_color", "color"),
    ("IndeterminateProgressIndicator", "indicator_color", "color"),
    ("Row", "equal_height", "intrinsic_size"),
    ("Column", "equal_width", "intrinsic_size"),
];

/// Parameters that take `impl Into<Option<&str>>`: an argument that is not a string
/// literal is passed through `AsRef::<str>::as_ref`, which takes `String`, `&String` and
/// `&str` alike.
pub const STR_PARAMETERS: &[&str] = &["tear_off_key", "title", "restore_key", "section", "label"];

/// Builder methods that are slots: a closure that composes, wrapped in `Some(..)`.
pub const SLOTS: &[&str] = &[
    "top_bar",
    "bottom_bar",
    "floating_action",
    "anchor",
    "head",
    "foot",
];

pub fn is_widget(name: &str) -> bool {
    WIDGETS.contains(&name)
}

pub fn main_handler(widget: &str) -> Option<&'static MainHandler> {
    MAIN_HANDLERS.iter().find(|main| main.widget == widget)
}

pub fn data_method(widget: &str) -> Option<(&'static str, &'static str)> {
    DATA_METHODS
        .iter()
        .find(|(name, _, _)| *name == widget)
        .map(|(_, method, empty)| (*method, *empty))
}

pub fn parameter(widget: &str, method: &str) -> String {
    for (name, from, to) in RENAMES {
        if (*name == widget || *name == "*") && *from == method {
            return (*to).to_owned();
        }
    }
    method.to_owned()
}

/// Whether a method is an optional handler or a slot.
pub fn is_optional(widget: &str, method: &str) -> bool {
    let main = main_handler(widget).map(|main| main.method);
    (method.starts_with("on_") && Some(method) != main) || SLOTS.contains(&method)
}

/// The argument types of an optional handler's closure, by method. Inside `Some(..)`
/// rustc no longer infers them from the parameter's bound, so the codemod writes them.
/// `{crate}` is replaced with the path the call sites use for compose-rust.
pub fn handler_argument_types(method: &str) -> Option<&'static [&'static str]> {
    Some(match method {
        "on_key_down" | "on_key_up" => &["{crate}::KeyEvent"],
        "on_motion_finished" => &["{crate}::MotionFinished"],
        "on_pointer" => &["{crate}::PointerEvent"],
        "on_window_drag_over" => &["{crate}::windows::WindowDragOver"],
        "on_moved" => &["{crate}::windows::WindowFrame"],
        "on_drag" => &["{crate}::windows::WindowDragEvent"],
        "on_submit" => &["String"],
        "on_composition_change" | "on_focus_change" | "on_focus_changed" => &["bool"],
        "on_click" | "on_focus_gained" | "on_focus_lost" | "on_dismiss" | "on_closed"
        | "on_unavailable" | "on_files_entered" => &[],
        _ => return None,
    })
}
